**独立参考解答（非原书摘录）**

设表达式 DAG 的弧由运算符顶点指向操作数顶点；每个运算符恰有两条出弧，邻接表顺序固定为左操作数、右操作数。根为唯一入度为 0 的顶点，原子顶点保存一个字母，运算符顶点保存四则运算符。

~~~~c
Status EmitRPN(const ALGraph *G, int u) {
    ArcNode *p = G->vertices[u].firstarc;
    if (G->vertices[u].kind == ATOM) {
        if (p != NULL) return ERROR;
        PutChar(G->vertices[u].atom);
        return OK;
    }
    if (p == NULL || p->nextarc == NULL || p->nextarc->nextarc != NULL)
        return ERROR;
    if (EmitRPN(G, p->adjvex) != OK) return ERROR;
    if (EmitRPN(G, p->nextarc->adjvex) != OK) return ERROR;
    PutChar(G->vertices[u].op);
    return OK;
}
~~~~

调用前可用三色 DFS 核验从根可达部分无环、原子无出弧、运算符恰有两条有序出弧。递归规则是左子式后缀式、右子式后缀式、运算符；对叶子和运算符作结构归纳可知输出正是整式的逆波兰表达式。

输出时不能对顶点作永久访问标记：共享子式在每个被引用的位置都必须重新输出。设展开后输出记号数为 $L$，时间为 $\Theta(L)$、递归栈为 $O(h)$；若图本身是树，$L=\Theta(|V|+|E|)$，共享 DAG 的展开长度则可能大于图规模。

**独立参考解答（非原书摘录）**

改用二叉链表后，左、右孩子指针直接保存两个操作数的位置，因此对根作后序遍历即可。允许多个父结点的孩子指针指向同一结点以表示公共子式；此时仍不能把第二次访问跳过。

~~~~c
typedef enum { ATOM, OP } NodeKind;
typedef struct BiNode {
    NodeKind kind;
    union { char atom; char op; } data;
    struct BiNode *lchild, *rchild;
} BiNode, *Expr;

Status EmitRPN2(Expr p) {
    if (p == NULL) return ERROR;
    if (p->kind == ATOM) {
        if (p->lchild != NULL || p->rchild != NULL) return ERROR;
        PutChar(p->data.atom);
        return OK;
    }
    if (p->lchild == NULL || p->rchild == NULL) return ERROR;
    if (EmitRPN2(p->lchild) != OK || EmitRPN2(p->rchild) != OK)
        return ERROR;
    PutChar(p->data.op);
    return OK;
}
~~~~

叶子输出自身；运算符结点先输出左、右子式，再输出本运算符，故后序遍历归纳证明结果正确。题设保证无环；输入可能损坏时应另用三色 DFS 检验。设展开表达式长度为 $L$，输出时间为 $\Theta(L)$、递归栈为 $O(h)$；无共享时为 $\Theta(n)$ 时间。

**独立参考解答（非原书摘录）**

用顶点表区分整数原子和字符运算符；弧仍从运算符指向左右操作数，邻接表顺序为左、右。题目仅规定原子为整数，未说明除法结果域；以下明确采用带溢出检查的机器整数运算，除法向零截断并拒绝除零。若题设要求实数除法，把结果类型改为 double 即可，遍历策略不变。

~~~~c
typedef enum { ATOM, OP } VKind;
typedef struct ArcNode {
    int adjvex;
    struct ArcNode *nextarc;
} ArcNode;
typedef struct {
    VKind kind;
    union { long long value; char op; } data;
    ArcNode *firstarc;
} VNode;
typedef struct { VNode vertices[MAXV]; int vexnum; } ALGraph;

Status Eval(const ALGraph *G, int u, unsigned char state[],
            long long memo[], long long *answer) {
    ArcNode *a;
    long long x, y, z;
    if (u < 0 || u >= G->vexnum) return ERROR;
    if (state[u] == 2) { *answer = memo[u]; return OK; }
    if (state[u] == 1) return ERROR;
    state[u] = 1;
    a = G->vertices[u].firstarc;
    if (G->vertices[u].kind == ATOM) {
        if (a != NULL) return ERROR;
        z = G->vertices[u].data.value;
    } else {
        if (a == NULL || a->nextarc == NULL || a->nextarc->nextarc != NULL)
            return ERROR;
        if (Eval(G, a->adjvex, state, memo, &x) != OK ||
            Eval(G, a->nextarc->adjvex, state, memo, &y) != OK)
            return ERROR;
        if (CheckedBinary(G->vertices[u].data.op, x, y, &z) != OK)
            return ERROR;
    }
    state[u] = 2;
    memo[u] = z;
    *answer = z;
    return OK;
}
~~~~

CheckedBinary 分别处理四则运算，并在未知运算符、整数溢出或除数为 0 时返回 ERROR。初始令 state 全为 0，从根调用 Eval。灰色结点表示当前递归路径，故能拒绝环；黑色结点已有唯一的纯表达式值，复用 memo 不会改变结果。按 DAG 的依赖关系归纳，每个缓存值就是相应子表达式值，所以根值正确。

每个顶点和弧至多处理一次，时间为 $O(|V|+|E|)$；状态、缓存和递归栈共为 $O(|V|)$ 空间。

**独立参考解答（非原书摘录）**

按教材的 AOE 网解释：弧表示活动，弧权为非负持续时间；source 是唯一源事件，sink 是唯一汇事件，所有事件均从源可达且能到达汇。邻接表弧结点含 adjvex 和 weight。下面先用 DFS 退出次序得到拓扑序，再在其正、逆序上计算事件的最早、最迟发生时间。

~~~~c
Status DfsFinish(const ALGraph *G, int u, int color[],
                 int finish[], int *nf) {
    ArcNode *p;
    color[u] = 1;
    for (p = G->vertices[u].firstarc; p != NULL; p = p->nextarc) {
        int v = p->adjvex;
        if (color[v] == 1) return ERROR;
        if (color[v] == 0 && DfsFinish(G, v, color, finish, nf) != OK)
            return ERROR;
    }
    color[u] = 2;
    finish[(*nf)++] = u;
    return OK;
}

Status CriticalPathByDFS(const ALGraph *G, int source, int sink) {
    int color[MAXV] = {0}, finish[MAXV], ve[MAXV], vl[MAXV];
    int n = G->vexnum, nf = 0, i, u, project;
    ArcNode *p;
    if (source < 0 || source >= n || sink < 0 || sink >= n) return ERROR;
    if (DfsFinish(G, source, color, finish, &nf) != OK || nf != n)
        return ERROR;
    for (i = 0; i < n; ++i) ve[i] = 0;
    for (i = n - 1; i >= 0; --i) {
        u = finish[i];
        for (p = G->vertices[u].firstarc; p; p = p->nextarc)
            if (ve[u] + p->weight > ve[p->adjvex])
                ve[p->adjvex] = ve[u] + p->weight;
    }
    project = ve[sink];
    for (i = 0; i < n; ++i) vl[i] = project;
    for (i = 0; i < n; ++i) {
        u = finish[i];
        for (p = G->vertices[u].firstarc; p; p = p->nextarc)
            if (vl[p->adjvex] - p->weight < vl[u])
                vl[u] = vl[p->adjvex] - p->weight;
    }
    for (u = 0; u < n; ++u)
        for (p = G->vertices[u].firstarc; p; p = p->nextarc) {
            int ee = ve[u], el = vl[p->adjvex] - p->weight;
            if (ee == el) PrintCriticalActivity(u, p->adjvex, p->weight);
        }
    return OK;
}
~~~~

无环图的 DFS 退出序逆序是拓扑序，所以第一轮处理弧 u 到 v 时，u 的所有前驱已处理，归纳得 ve[v] 为所有 ve[u]+weight(u,v) 的最大值；第二轮反向处理得 vl[u] 为所有 vl[v]-weight(u,v) 的最小值。活动的最早开工时间为 ve[u]，最迟开工时间为 vl[v]-weight(u,v)，二者相等当且仅当活动无时差，故输出恰为关键活动。要列出多条关键路径，可只沿零时差弧从 source 深度优先到 sink；枚举另加与输出总长度成正比的时间。

不计路径枚举时，DFS、两次弧扫描和活动判定均为 $O(|V|+|E|)$，辅助数组和递归栈为 $O(|V|)$。

**独立参考解答（非原书摘录）**

设带权有向图采用邻接表，弧结点含 adjvex、weight、nextarc。Dijkstra 的前提是所有弧权非负；dist[v] 是当前从源点到 v 的最短上界，prev[v] 记录最后一条松弛弧的前驱。以下版本采用教材的逐数组选择，同时只沿邻接表扫描真实出弧。

~~~~c
Status DijkstraList(const ALGraph *G, int s, long long dist[], int prev[]) {
    const long long INF = LLONG_MAX / 4;
    bool final[MAXV] = {false};
    int n = G->vexnum, i, u, v;
    ArcNode *p;
    if (s < 0 || s >= n) return ERROR;
    for (i = 0; i < n; ++i) { dist[i] = INF; prev[i] = -1; }
    dist[s] = 0;
    for (i = 0; i < n; ++i) {
        u = -1;
        for (v = 0; v < n; ++v)
            if (!final[v] && (u < 0 || dist[v] < dist[u])) u = v;
        if (u < 0 || dist[u] == INF) break;
        final[u] = true;
        for (p = G->vertices[u].firstarc; p; p = p->nextarc) {
            v = p->adjvex;
            if (p->weight < 0) return ERROR;
            if (!final[v] && dist[u] <= INF - p->weight &&
                dist[u] + p->weight < dist[v]) {
                dist[v] = dist[u] + p->weight;
                prev[v] = u;
            }
        }
    }
    return OK;
}
~~~~

对 dist 有限的终点，从终点反复沿 prev 回溯至源再反转，即得到一条最短路径；保持 INF 的顶点不可达。每轮选出的 u 是所有未确定顶点中当前距离最小者。因未松弛弧权非负，任何经未确定顶点绕行的路径不会更短，故 u 被置为 final 时距离已最终确定；松弛保持其余顶点的最短已知上界，归纳即得正确性。

数组选最小值为 $O(|V|^2)$，每条邻接表弧最多松弛一次，故时间为 $O(|V|^2+|E|)=O(|V|^2)$，额外空间为 $O(|V|)$。用支持 decrease-key 的最小堆替换数组选择，可达 $O((|V|+|E|)\log |V|)$。

**独立参考解答（非原书摘录）**

最后分配者最先释放时，已释放空间必与堆顶相邻，适合用栈式分配器，无须按大小维护可利用空间表。令 $[low,high)$ 是一个连续字节数组，top 为下一块首地址，last 为最近分配块的头。每个已分配块在用户区之前放块头，保存总长度和前一个块头。

~~~~c
#include <stddef.h>
#include <stdint.h>
#include <stdbool.h>

typedef unsigned char Byte;
typedef struct Header {
    size_t total;
    struct Header *prev;
} Header;
typedef struct {
    Byte *low, *high, *top;
    Header *last;
} LifoHeap;

enum { ALIGN = _Alignof(max_align_t) };
#define HDR (((sizeof(Header) + ALIGN - 1) / ALIGN) * ALIGN)

static bool NeedFor(size_t n, size_t *need) {
    size_t total, remainder;
    if (n == 0 || n > SIZE_MAX - HDR) return false;
    total = HDR + n;
    remainder = total % ALIGN;
    if (remainder != 0) {
        if (total > SIZE_MAX - (ALIGN - remainder)) return false;
        total += ALIGN - remainder;
    }
    *need = total;
    return true;
}

void *AllocateLifo(LifoHeap *H, size_t n) {
    size_t need;
    Header *b;
    if (H == NULL || H->low > H->top || H->top > H->high ||
        !NeedFor(n, &need)) return NULL;
    if (need > (size_t)(H->high - H->top)) return NULL;
    b = (Header *)H->top;
    b->total = need;
    b->prev = H->last;
    H->last = b;
    H->top += need;
    return (void *)((Byte *)b + HDR);
}
~~~~

初始化为 top=low、last=NULL，并要求 low 已按最大对齐边界对齐；因每块总长均为 ALIGN 的倍数，之后的块头也保持对齐。NeedFor 拒绝零长度申请、总长度溢出和对齐进位溢出；成功时用户区恰有至少 n 字节且不越过 high。每次只移动堆顶并压入一个块头，故分配时间为 $O(1)$；除每块固定头部外不使用额外表空间，元数据总量为 $O(\text{分配块数})$。

**独立参考解答（非原书摘录）**

沿用 8.11 的 LifoHeap、Header 与 HDR。释放接口接受用户区指针 p，但只有它恰为最近一次分配返回的指针时才允许释放；其他顺序违反题设的 LIFO 约束，必须报告错误而不能制造中间空洞。

~~~~c
Status ReleaseLifo(LifoHeap *H, void *p) {
    Header *b;
    if (H == NULL || H->last == NULL || p == NULL) return ERROR;
    b = H->last;
    if (p != (void *)((Byte *)b + HDR)) return ERROR;
    if (b->total < HDR || (Byte *)b + b->total != H->top)
        return ERROR;
    H->top = (Byte *)b;
    H->last = b->prev;
    return OK;
}
~~~~

恢复 top 到块头起始地址后，整块立即成为连续的堆顶可用空间；下次分配可覆盖其头部和用户区。空堆释放、空指针、非最近块和损坏长度均被拒绝。正确性来自不变式：last 总是区间 low 到 top 中最后一个块的头，且该块尾恰为 top；一次成功释放恢复前一块头，故不变式仍成立。时间为 $O(1)$，额外空间为 $O(1)$。

**独立参考解答（非原书摘录）**

按 8.6 的四步完成紧缩：先计算每个占用块的新地址，再修改初始变量表和块中全部指针，随后迁移块，最后把尾部重建为一个空闲块。设堆是连续字节区 $[low,high)$；每个物理块的首部含总大小 size（含首部）和 tag，其中 tag=1 为占用、tag=0 为空闲。输入前提是所有非空根指针和对象内已登记的指针域都指向某个占用块内；对象的布局描述符能枚举这些指针域。没有这种字段约定，程序不能从任意字节中安全识别指针。

~~~~c
#include <string.h>
typedef unsigned char Byte;
typedef struct { size_t size; unsigned char tag; } BlockHeader;
typedef struct { Byte *old; size_t size; Byte *to; } Move;
typedef struct { Byte *low, *high, *avail; } Heap;
typedef Status (*SlotVisitor)(Byte **slot, const Move map[], int count);

static Status RelocatePointer(Byte *q, const Move map[], int count,
                              Byte **out) {
    int i;
    if (q == NULL) { *out = NULL; return OK; }
    for (i = 0; i < count; ++i)
        if (q >= map[i].old && q < map[i].old + map[i].size) {
            *out = map[i].to + (q - map[i].old);
            return OK;
        }
    return ERROR;
}

static Status RelocateSlot(Byte **slot, const Move map[], int count) {
    Byte *newValue;
    if (slot == NULL || RelocatePointer(*slot, map, count, &newValue) != OK)
        return ERROR;
    *slot = newValue;
    return OK;
}

/* 由对象布局描述符实现：只枚举 payload 中真实的 Byte* 指针域。 */
Status ForEachPointerSlot(Byte *payload, size_t payloadBytes,
                          SlotVisitor visit, const Move map[], int count);

static void WriteFreeHeader(Byte *p, size_t size) {
    BlockHeader *h = (BlockHeader *)p;
    h->size = size;
    h->tag = 0;
}

Status Compact(Heap *H, Byte **roots, int rootCount) {
    Move move[MAX_BLOCKS];
    int b = 0, i;
    Byte *p, *dst;
    if (H == NULL || rootCount < 0 || (rootCount != 0 && roots == NULL))
        return ERROR;

    /* 第 1 步：按旧地址递增扫描，建立旧区间到新区间的映射。 */
    for (p = H->low, dst = H->low; p < H->high; ) {
        BlockHeader *h = (BlockHeader *)p;
        if (h->size < sizeof *h || h->size > (size_t)(H->high - p) ||
            (h->tag != 0 && h->tag != 1)) return ERROR;
        if (h->tag == 1) {
            if (b == MAX_BLOCKS) return ERROR;
            move[b++] = (Move){ p, h->size, dst };
            dst += h->size;
        }
        p += h->size;
    }

    /* 第 2 步：块尚未搬动，先改根指针和占用块 payload 的指针。 */
    for (i = 0; i < rootCount; ++i)
        if (RelocatePointer(roots[i], move, b, &roots[i]) != OK) return ERROR;
    for (i = 0; i < b; ++i)
        if (ForEachPointerSlot(move[i].old + sizeof(BlockHeader),
              move[i].size - sizeof(BlockHeader), RelocateSlot, move, b) != OK)
            return ERROR;

    /* 第 3 步：目的地址不高于源地址，按旧地址递增移动。 */
    for (i = 0; i < b; ++i)
        memmove(move[i].to, move[i].old, move[i].size);

    /* 第 4 步：占用块之后的全部空间合成一个空闲块。 */
    if (dst < H->high) WriteFreeHeader(dst, (size_t)(H->high - dst));
    H->avail = dst;
    return OK;
}
~~~~

RelocatePointer 保留空指针；对非空指针 q 在按旧首地址有序的 move 表中找到唯一满足 old≤q<old+size 的项，并令新值为 to+(q-old)，因而同时支持指向块首和指向块内偏移的指针，找不到即拒绝不满足前提的输入。第二步在迁移前完成，所以根和内部引用已变为新地址；第三步按地址递增移动时，每一目标块的起点不高于其源块起点、终点不越过该源块尾，故不会覆盖尚待读取的后继占用块；第四步保证所有碎片合并为尾部唯一空闲块。

设物理块数为 B、占用单元总量为 L、根和内部指针域总数为 P。映射表二分定位时总时间为 $O(B+L+P\log B)$，额外映射空间为 $O(B)$；若块头预留转发表且所有指针只指向块首，可把重定位降为每指针 $O(1)$。

