            (h->tag != 0 && h->tag != 1)) return ERROR;
        if (h->tag == 1) {
            if (b == MAX_BLOCKS) return ERROR;
            move[b++] = (Move){ p, h->size, dst };
            dst += h->size;
        }
        p += h->size;
    }

    /* 第 2 步：块尚未搬动，先改根指针和占用块 payload 的指针。 */
    for (i = 0; i < rootCount; ++i)
        if (RelocatePointer(roots[i], move, b, &roots[i]) != OK) return ERROR;
    for (i = 0; i < b; ++i)
        if (ForEachPointerSlot(move[i].old + sizeof(BlockHeader),
              move[i].size - sizeof(BlockHeader), RelocateSlot, move, b) != OK)
            return ERROR;

    /* 第 3 步：目的地址不高于源地址，按旧地址递增移动。 */
    for (i = 0; i < b; ++i)
        memmove(move[i].to, move[i].old, move[i].size);

    /* 第 4 步：占用块之后的全部空间合成一个空闲块。 */
    if (dst < H->high) WriteFreeHeader(dst, (size_t)(H->high - dst));
    H->avail = dst;
    return OK;
}
~~~~

第一步按物理旧地址扫描，因此 move 表中的 old 严格递增；RelocatePointer 的二分循环每次排除一半候选块。对非空指针 q，找到唯一满足 old≤q<old+size 的项后改写为 to+(q-old)，因而同时支持指向块首和指向块内偏移的指针，找不到即拒绝不满足前提的输入。第二步在迁移前完成，所以根和内部引用已变为新地址；第三步按地址递增移动时，每一目标块的起点不高于其源块起点、终点不越过该源块尾，故不会覆盖尚待读取的后继占用块；第四步保证所有碎片合并为尾部唯一空闲块。

设物理块数为 B、占用单元总量为 L、根和内部指针域总数为 P。扫描建表为 $O(B)$，二分重定位每个指针为 $O(\log B)$，搬迁为 $O(L)$，故总时间为 $O(B+L+P\log B)$，额外映射空间为 $O(B)$；若块头预留转发表且所有指针只指向块首，可把重定位降为每指针 $O(1)$。

